param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1,[switch]$LeavePendingReceipt)
$ErrorActionPreference="Stop"
function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session "hq";$agency=Session "agency";$client=Session "client";$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/customer-timeline";$workspace=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh;$used=@($workspace.timelines|ForEach-Object {$_.account_reference});$account=($workspace.sources|Group-Object account_reference|Where-Object {(($_.Group.source_type|Sort-Object -Unique).Count -eq 5) -and $used -notcontains $_.Name}|Select-Object -First 1).Name;if(-not $account){throw "Missing unused account with all five authority event types"}
$timeline=Post "$root/timelines" @{timeline_name="Governed customer journey $stamp";account_reference=$account} $hh;$events=@();foreach($kind in @("marketing-touchpoint","inquiry-flow","cpq-quote","fulfillment-order","service-ticket")){$source=$workspace.sources|Where-Object {$_.account_reference -eq $account -and $_.source_type -eq $kind}|Sort-Object occurred_at|Select-Object -First 1;if(-not $source){throw "Missing $kind source"};$event=Post "$root/timelines/$($timeline.id)/events" @{source_type=$kind;source_id=$source.source_id} $hh;$events+=Post "$root/events/$($event.id)/verify" @{expected_revision=$event.revision;reference="TIMELINE-EVENT-VERIFY-$kind-$stamp"} $ah}
$quoteEvent=$events|Where-Object {$_.source_type -eq "cpq-quote"}|Select-Object -First 1;$checkpoint=Post "$root/timelines/$($timeline.id)/checkpoints" @{event_id=$quoteEvent.id;checkpoint_code="quote-accepted";note="Verified commercial intent milestone"} $hh;$published=Post "$root/timelines/$($timeline.id)/publish" @{expected_revision=$timeline.revision;consumers=@("crm","cdp","sales","service");delivery_reference_prefix="CUSTOMER-TIMELINE-$stamp"} $ah;$publications=@();if($LeavePendingReceipt){$publications=$published.publications}else{foreach($publication in $published.publications){$publications+=Post "$root/publications/$($publication.id)/acknowledge" @{expected_revision=$publication.revision;reference="CUSTOMER-TIMELINE-ACK-$($publication.consumer)-$stamp"} $ch}};$workspace=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh
[pscustomobject]@{project_id=$ProjectId;timeline_number=$published.timeline.timeline_number;version_reference=$published.version.version_reference;manifest_hash=$published.version.manifest_hash;event_count=$published.version.event_count;source_type_count=$published.version.source_type_count;high_intent_event_count=$published.version.high_intent_event_count;checkpoint_number=$checkpoint.checkpoint_number;consumer_count=$publications.Count;acknowledged_publications=($publications|Where-Object {$_.status -eq "acknowledged"}).Count;hq=$hq.user.id;agency=$agency.user.id;client=$client.user.id;contract=$workspace.contract;metrics=$workspace.metrics}|ConvertTo-Json -Depth 8
